// Function to scale menu on window resize
function scale(x) {
    const menuToggle = document.getElementById("menu-toggle");
    const lightboxes = document.querySelectorAll("[id^='Lightbox_']");

    // Check if any lightbox is currently open (display: flex)
    const anyLightboxOpen = Array.from(lightboxes).some(
        (lightbox) => window.getComputedStyle(lightbox).display === "flex"
    );

    if (x.matches && !anyLightboxOpen) {
        // Only show menu-toggle if no lightbox is open
        menuToggle.style.display = "flex";
    } else {
        menuToggle.style.display = "none";
    }
}

// Media query listener setup
var x = window.matchMedia("(max-width: 1000px)");
scale(x); // Call listener function at runtime
x.addListener(scale); // Attach listener function on state changes

document.addEventListener("DOMContentLoaded", function() {
    console.log("DOM fully loaded and parsed");

    // Initialize the lightboxes when DOM is ready
    initializeLightboxes();

    // Preload the first media item for the first lightbox
    preloadFirstMedia();
});

// Function to initialize the lightboxes
function initializeLightboxes() {
    console.log("Initializing lightboxes");

    // Select all elements with the class 'modal' (lightbox class)
    const lightboxes = document.querySelectorAll(".modal");
    console.log("Found lightboxes:", lightboxes.length);

    if (lightboxes.length === 0) {
        console.error("No lightboxes found. Check your HTML.");
        return;
    }

    // Generate an array of folder names dynamically
    const folderNames = Array.from(lightboxes).map(
        (lightbox, index) => `lightbox_${index + 1}`
    );

    // Fetch media for all lightboxes in one batch
    fetchMediaBatch(folderNames);
}

// Function to preload the first media item (e.g., the first image/video in the first lightbox)
function preloadFirstMedia() {
    console.log("Preloading the first media item");

    const firstLightbox = document.querySelector(".modal");
    if (firstLightbox) {
        const firstMedia = firstLightbox.querySelector("img");
        if (firstMedia) {
            console.log("Preloading first media item:", firstMedia.src);
            const img = new Image();
            img.src = firstMedia.src; // Preload the image

            // Store the first image in sessionStorage to prevent it from being fetched again
            sessionStorage.setItem(
                `firstMedia_lightbox_${firstLightbox.id}`,
                JSON.stringify([{ src: firstMedia.src, alt: firstMedia.alt }])
            );
        }
    }
}

function fetchMediaBatch(folderNames) {
    console.log(`Fetching media for folders: ${folderNames.join(", ")}`);

    fetch(
            `https://new-vhym.onrender.com/api/get-cloudinary-media?folders=${folderNames.join(
      ","
    )}`
        )
        .then((response) => {
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            return response.json();
        })
        .then((data) => {
            let addedFolders = {}; // To track which folders have had their first image inserted

            // Process the response and insert only the first media of each folder
            data.forEach((media) => {
                const folderName = media.folder; // Get the folder name from the response
                const lightbox = document.getElementById(
                    folderName.charAt(0).toUpperCase() + folderName.slice(1)
                ); // Capitalize the folder name for the ID (e.g. lightbox_1 => Lightbox_1)

                if (lightbox && !addedFolders[folderName]) {
                    // Insert only the first media of each folder
                    insertFirstImage(media, lightbox, folderName);
                    addedFolders[folderName] = true; // Mark first image as inserted
                    console.log(`Inserted first media for ${folderName}`);
                }
            });
        })
        .catch((error) => {
            console.error("Error fetching media:", error);
        });
}

function insertFirstImage(media, lightbox, folderName) {
    console.log(`Inserting first media for ${folderName}: ${media.src}`);

    // Create an image element
    const mediaElement = document.createElement('img');
    mediaElement.src = media.src;
    mediaElement.alt = media.alt;
    mediaElement.classList.add("image-slide", "inj"); // Add "inj" and "image-slide" classes

    // Set the width and height to 100% to make it fill the container

    mediaElement.style.width = "100%";
    mediaElement.style.height = "100%";

    // Create a slide div and assign the correct class (slide slide15, slide slide10, etc.)
    const slide = document.createElement('div');
    const lightboxNumber = folderName.split('_')[1]; // Extract the number part of the folder name (e.g., '15' from 'lightbox_15')
    const slideClass = `slide${lightboxNumber}`; // Use slideX as the class name
    slide.classList.add('slide');
    slide.classList.add(slideClass);
    slide.appendChild(mediaElement);

    // Now hide the parent div (the slide div)
    slide.style.display = "none"; // Hide the 'slide' div (the parent of the img tag)

    // Append to modal-content inside the lightbox
    const modalContent = lightbox.querySelector(".modal-content");
    if (modalContent) {
        modalContent.appendChild(slide);
        console.log(`Added first media to ${folderName}: ${media.src}`);
        sessionStorage.setItem(`firstMediaInserted_${folderName}`, true); // Mark the first media as inserted
    } else {
        console.error(`modal-content not found in ${folderName}`);
    }
}

function insertRemainingMedia(media, lightbox, folderName) {
    // Check if the image is already added
    const mediaAlreadyInserted = lightbox.querySelector(
        `img[src="${media.src}"]`
    );
    if (mediaAlreadyInserted) {
        console.log(`Media ${media.src} already inserted, skipping.`);
        return;
    }

    console.log(`Inserting remaining media for ${folderName}: ${media.src}`);

    const mediaElement = document.createElement("img");
    mediaElement.src = media.src;
    mediaElement.alt = media.alt;
    mediaElement.classList.add("image-slide", "inj");

    // Set the width and height to 100% to make it fill the container
    mediaElement.style.width = "100%";
    mediaElement.style.height = "100%";


    const slide = document.createElement("div");
    const lightboxNumber = folderName.split("_")[1]; // Assuming folderName is something like 'lightbox_X'
    const slideClass = `slide${lightboxNumber}`; // Generate class like slide1, slide2, etc.
    slide.classList.add('slide');
    slide.classList.add(slideClass); // Use the dynamic class for the slide

    slide.appendChild(mediaElement);

    // Now hide the parent div (the slide div)
    slide.style.display = "none"; // Hide the 'slide' div (the parent of the img tag)

    const modalContent = lightbox.querySelector(".modal-content");
    if (modalContent) {
        modalContent.appendChild(slide);
        console.log(`Added remaining media to ${folderName}: ${media.src}`);
    } else {
        console.error(`modal-content not found in ${folderName}`);
    }
}

function displayMediaFiles(mediaFiles, lightboxId, folderName) {
    console.log("lightboxId value: ", lightboxId); // Log the lightboxId value to inspect it
    console.log("folderName value: ", folderName); // Log folderName to check if it's undefined

    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);
    const modalContent = lightbox.querySelector(".modal-content");

    if (!modalContent) return;

    // Make sure folderName is defined and can be split
    if (folderName) {
        mediaFiles.forEach(media => {
            // Avoid inserting the same media again
            const mediaAlreadyInserted = lightbox.querySelector(`img[src="${media.src}"]`);
            if (mediaAlreadyInserted) {
                console.log(`Media ${media.src} already inserted, skipping.`);
                return;
            }

            // Create an image element
            const mediaElement = document.createElement('img');
            mediaElement.src = media.src;
            mediaElement.alt = media.alt;
            mediaElement.classList.add("image-slide", "inj"); // Add "inj" and "image-slide" classes

            // Set the width and height to 100% to make it fill the container
            mediaElement.style.width = "100%";
            mediaElement.style.height = "100%";


            // Ensure folderName is valid before using split
            const lightboxNumber = folderName.split('_')[1]; // Extract the number part of the folder name (e.g., '15' from 'lightbox_15')
            const slideClass = `slide${lightboxNumber}`; // Use slideX as the class name
            const slide = document.createElement('div');

            slide.classList.add('slide');
            slide.classList.add(slideClass);
            slide.appendChild(mediaElement);

            // Now hide the parent div (the slide div)
            slide.style.display = "none"; // Hide the 'slide' div (the parent of the img tag)



            // Append the slide to the modal-content
            modalContent.appendChild(slide);
            console.log(`Added remaining media: ${media.src}`);
        });
    } else {
        console.error("folderName is undefined or invalid!");
    }
}



let slideIndex = 1; // Initialize globally
let mediaLoaded = {}; // Object to track if media has been loaded for each lightbox

let lastScrollPosition = 0;

function loadMedia(lightboxId) {
    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);
    const mediaContainer = lightbox.querySelector(".modal-content");

    if (!mediaContainer) return;

    // Check if the media for this lightbox is already in sessionStorage
    if (sessionStorage.getItem(`media_${lightboxId}`)) {
        console.log(`Media for Lightbox ${lightboxId} already cached. Using cached data.`);
        const cachedMedia = JSON.parse(sessionStorage.getItem(`media_${lightboxId}`));
        displayMediaFiles(cachedMedia, lightboxId);
        return;
    }

    // Fetch media from the server if not cached
    const folderName = `lightbox_${lightboxId}`;
    console.log(`Fetching media for folder: ${folderName}`); // Log the folderName here as well
    fetchMediaData(folderName, lightboxId); // Fetch from server if not cached
}


function fetchMediaData(folderName, lightboxId, retries = 3) {
    console.log(`Fetching media for folder: ${folderName}`); // Log the folderName being passed

    fetch(
            `https://new-vhym.onrender.com/api/get-cloudinary-media?folder=${folderName}`
        )
        .then((response) => response.json())
        .then((mediaFiles) => {
            console.log("Fetched media files:", mediaFiles);

            // Cache the media data in sessionStorage
            sessionStorage.setItem(`media_${lightboxId}`, JSON.stringify(mediaFiles));

            // Insert the media into the lightbox
            displayMediaFiles(mediaFiles, lightboxId, folderName);
        })
        .catch((err) => {
            console.error("Error loading media:", err);
            if (retries > 0) {
                console.log(`Retrying... Remaining retries: ${retries}`);
                setTimeout(
                    () => fetchMediaData(folderName, lightboxId, retries - 1),
                    2000
                );
            } else {
                alert(`Error loading media for Lightbox ${lightboxId}: ${err.message}`);
            }
        });
}




// Function to open the lightbox
function openLightbox(lightboxId) {
    console.log("Opening lightbox with id: ", lightboxId); // Log the lightboxId value
    loadMedia(lightboxId);
    document.querySelectorAll("[id^='Lightbox_']").forEach(lightbox => {
        if (lightbox.id !== `Lightbox_${lightboxId}`) {
            lightbox.style.display = "none";
        }
    });

    document.getElementById(`Lightbox_${lightboxId}`).style.display = "flex";
    document.getElementById(`projecttitle_${lightboxId}`).style.display = "block";
    document.getElementById("mouseTarget").style.display = "none";
    document.body.style.overflow = "hidden";
    document.getElementById("rowid").style.display = "none";
    document.querySelector("footer").style.display = "none";
    document.getElementById("social_elements2").style.display = "none";

    setKeys(lightboxId);
    scale(x);
    // Retrieve the last slide index from sessionStorage
    const lastSlide = sessionStorage.getItem(`lastSlide_${lightboxId}`);
    if (lastSlide) {
        toSlide(lightboxId, parseInt(lastSlide)); // Go to the last known slide
    } else {
        toSlide(lightboxId, 1); // If no last slide, start from the first
    }
}


// Function to store the last viewed slide
function storeLastSlide(lightboxId, slideIndex) {
    sessionStorage.setItem(`lastSlide_${lightboxId}`, slideIndex); // Store the slide index in sessionStorage
}

// Function to change slides
function toSlide(lightboxId, slideIndex) {
    showSlide(lightboxId, slideIndex);
    storeLastSlide(lightboxId, slideIndex);
}

// Function to change slides
function changeSlide(NR, n) {
    slideIndex += n;
    let slides = document.getElementsByClassName(`slide${NR}`);

    if (slideIndex < 1) {
        slideIndex = slides.length;
    } else if (slideIndex > slides.length) {
        slideIndex = 1;
    }

    showSlide(NR, slideIndex);
    document.dispatchEvent(new Event("slideChange"));
}

// Function to show a specific slide
function showSlide(slideGroup, e) {
    let slides = document.getElementsByClassName(`slide${slideGroup}`);
    if (e > slides.length) slideIndex = 1;
    else if (e < 1) slideIndex = slides.length;
    else slideIndex = e;

    for (let n = 0; n < slides.length; n++) {
        slides[n].style.display = "none";
        slides[n].classList.remove("active-slide", "previous-slide", "next-slide");
    }

    // If only one slide is present, set it as active-slide only
    if (slides.length === 1) {
        slides[0].style.display = "flex";
        slides[0].classList.add("active-slide");
    } else {
        if (slides[slideIndex - 1]) {
            slides[slideIndex - 1].style.display = "flex";
            slides[slideIndex - 1].classList.add("active-slide");
        }

        let prevIndex = slideIndex - 2 >= 0 ? slideIndex - 2 : slides.length - 1;
        if (slides[prevIndex]) {
            slides[prevIndex].style.display = "flex";
            slides[prevIndex].classList.add("previous-slide");
        }

        let nextIndex = slideIndex < slides.length ? slideIndex : 0;
        if (slides[nextIndex]) {
            slides[nextIndex].style.display = "flex";
            slides[nextIndex].classList.add("next-slide");
        }

        // Preload the next 2 slides
        preloadNextSlides(slideGroup, slideIndex);
    }

    storeLastSlide(slideGroup, slideIndex);
    // Function to show a specific slide
    function showSlide(slideGroup, e) {
        let slides = document.getElementsByClassName(`slide${slideGroup}`);
        if (e > slides.length)
            slideIndex = 1; // If the slide index exceeds the number of slides, go back to the first
        else if (e < 1)
            slideIndex =
            slides.length; // If the index is less than 1, go to the last slide
        else slideIndex = e;

        // Hide all slides
        for (let n = 0; n < slides.length; n++) {
            slides[n].style.display = "none";
            slides[n].classList.remove(
                "active-slide",
                "previous-slide",
                "next-slide"
            );
        }

        // Show the current slide
        if (slides[slideIndex - 1]) {
            slides[slideIndex - 1].style.display = "flex";
            slides[slideIndex - 1].classList.add("active-slide");
        }

        // Preload the next slides
        let prevIndex = slideIndex - 2 >= 0 ? slideIndex - 2 : slides.length - 1;
        if (slides[prevIndex]) {
            slides[prevIndex].style.display = "flex";
            slides[prevIndex].classList.add("previous-slide");
        }

        let nextIndex = slideIndex < slides.length ? slideIndex : 0;
        if (slides[nextIndex]) {
            slides[nextIndex].style.display = "flex";
            slides[nextIndex].classList.add("next-slide");
        }

        // Preload the next 2 slides
        preloadNextSlides(slideGroup, slideIndex);
        storeLastSlide(slideGroup, slideIndex); // Save the current slide index when switching slides
    }
}

// Function to preload the next 2 slides after the current and next slide
function preloadNextSlides(slideGroup, currentSlideIndex) {
    const slides = document.getElementsByClassName(`slide${slideGroup}`);
    const nextSlides = [
        currentSlideIndex + 1,
        currentSlideIndex + 2,
        currentSlideIndex + 3,
    ]; // Next 3 slides

    nextSlides.forEach((index) => {
        if (slides[index]) {
            const img = slides[index].querySelector("img");
            if (img && img.loading !== "eager") {
                img.loading = "eager"; // Preload image
            }

            const video = slides[index].querySelector("video");
            if (video && video.preload !== "auto") {
                video.preload = "auto"; // Preload video
            }
        }
    });
}

// Lazy load and preload visible slides
document.addEventListener("DOMContentLoaded", function() {
    function preloadVisibleSlides() {
        document
            .querySelectorAll(
                ".active-slide img.image-slide, .next-slide img.image-slide, .previous-slide img.image-slide"
            )
            .forEach((img) => (img.loading = "eager"));
    }

    function lazyLoadOthers() {
        document.querySelectorAll("img.image-slide").forEach((img) => {
            if (!img.loading) img.loading = "lazy";
        });

        document.querySelectorAll("video.videofront").forEach((video) => {
            if (video.preload !== "auto") video.preload = "none";
        });
    }

    preloadVisibleSlides();
    lazyLoadOthers();
    document.addEventListener("slideChange", preloadVisibleSlides);
});

// Function to get the highest lightbox number
function getHighestLightboxNumber() {
    const lightboxes = document.querySelectorAll('[id^="Lightbox_"]');
    let highest = 0;
    lightboxes.forEach((lightbox) => {
        const id = lightbox.id;
        const number = parseInt(id.replace("Lightbox_", ""));
        if (number > highest) highest = number;
    });
    return highest;
}

// Function to set up pointer interaction
function setupPointer() {
    const Xmax = getHighestLightboxNumber();
    const pointerElement = document.getElementById("before-pointer");

    pointerElement.onclick = function() {
        openLightbox(Xmax);
        showSlide(Xmax, 1);
    };
}

window.onload = setupPointer;

// Function to close the lightbox
function closeLightbox(lightboxId) {
    document.getElementById(`Lightbox_${lightboxId}`).style.display = "none";
    pauseVideo(lightboxId);

    document.getElementById(`projecttitle_${lightboxId}`).style.display = "none";
    document.getElementById("mouseTarget").style.display = "flex";
    document.body.style.overflow = "";
    document.getElementById("rowid").style.display = "grid";
    document.querySelector("footer").style.display = "flex";
    document.getElementById("social_elements2").style.display = "";

    window.scrollTo({ top: lastScrollPosition, behavior: "smooth" });
    window.onkeydown = null;
    scale(x);
}

// Function to pause video when lightbox is closed
function pauseVideo(lightboxId) {
    document
        .querySelectorAll(`#Lightbox_${lightboxId} video`)
        .forEach((video) => {
            video.pause();
            video.currentTime = 0;
        });
}

// Function to set up key events for navigation
function setKeys(lightboxId) {
    window.onkeydown = function(e) {
        const key = e.key || e.code;

        if (key === "Escape") {
            closeLightbox(lightboxId);
        } else if (key === "ArrowRight") {
            changeSlide(lightboxId, 1);
        } else if (key === "ArrowLeft") {
            changeSlide(lightboxId, -1);
        }
    };
}